// Кейс: .qa/tests/expert/EXP-009.md (шаги 1–2) · план: .qa/e2e-app/specs/app.md (1.43)
// РУЧНОЕ ПРЕДУСЛОВИЕ: приложение залогинено под экспертом jleprog34, запуск с BANCI_ACCOUNT=jleprog34 (иначе — пропуск).
// Тест НИЧЕГО не сохраняет: «שמירת החוקים» не нажимается, перед выходом приложение перезапускается.
// RTL определяется по пикселям скриншота (lib/pixels.mjs): Appium не видит, с какой стороны нарисован текст внутри поля.
import { by, assert } from '../../lib/appium.mjs';
import { requireExpert, openExpert, fieldBelow, hideKeyboard, assertTextRtl, value } from '../../lib/expert.mjs';

export const name = '«חוקי זיהוי» → «מה נקבע ולמה»: строки, начинающиеся с латиницы/цифры, показаны в RTL (прижаты вправо); без сохранения #7581cb @iphone @app @prod-safe';

const LABEL = 'מה נקבע ולמה';

export default async function (app) {
  requireExpert();
  await openExpert(app);

  const field = await fieldBelow(app, LABEL);
  await field.click();
  // 1. Две строки: латиница+число в начале; латиница+цифра в начале второй (как проверено вручную 17.11).
  await field.type('QA 15.11 בדיקה\nYOLO 8 בדיקה');
  const typed = await value(field);
  assert(typed.includes('QA 15.11 בדיקה') && typed.includes('YOLO 8 בדיקה'), `в поле введены обе строки (сейчас «${typed}»)`);
  await hideKeyboard(app, LABEL);

  const fresh = await fieldBelow(app, LABEL);
  const lines = await assertTextRtl(app, fresh, 'поле «מה נקבע ולמה», строки с латиницы', { minLines: 2 });

  // 2. Контроль: строка с иврита тоже справа (не сломано).
  await fresh.click();
  await fresh.type('\nבדיקה QA');
  await hideKeyboard(app, LABEL);
  const control = await fieldBelow(app, LABEL);
  const all = await assertTextRtl(app, control, 'поле «מה נקבע ולמה», + строка с иврита', { minLines: 3 });
  assert(all.length >= lines.length + 1, 'добавленная строка с иврита видна отдельной строкой');

  assert(!(await app.exists(by.exact('החוקים נשמרו'))), 'ничего не сохранено');
  await app.restart();
}
